function maxArrayValue(nums) {
  // Explore every array reachable by any sequence of merges.
  const visited = new Set();
  const stack = [nums.slice()];
  let answer = 0;
  while (stack.length > 0) {
    const arr = stack.pop();
    const key = arr.join(',');
    if (visited.has(key)) continue;
    visited.add(key);
    for (const value of arr) answer = Math.max(answer, value);
    for (let i = 0; i + 1 < arr.length; i++) {
      if (arr[i] <= arr[i + 1]) {
        stack.push([...arr.slice(0, i), arr[i] + arr[i + 1], ...arr.slice(i + 2)]);
      }
    }
  }
  return answer;
}

