function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const n = pick(1500, 2000);
    const shape = pick(0, 2);
    const nums = [];
    for (let i = 0; i < n; i++) {
      if (shape === 0) nums.push(pick(1, 1000000));
      else if (shape === 1) nums.push(pick(1, 1000));
      else nums.push(rand() < 0.01 ? pick(500000, 1000000) : pick(1, 100));
    }
    return [nums];
  }
  const n = pick(1, 8);
  const high = [3, 10, 50][pick(0, 2)];
  const nums = Array.from({ length: n }, () => pick(1, high));
  if (rand() < 0.2) nums.sort((a, b) => a - b);
  else if (rand() < 0.2) nums.sort((a, b) => b - a);
  return [nums];
}
